import {saveAssetDialog,applyURL,libraryURL} from './library-client.js';
let scheduled=false;
function registryOutput(id){try{return globalThis.zhijingToolOutputs?.get?.(id)||null;}catch{return null;}}
function addStyle(){if(document.getElementById('libraryActionsStyle'))return;const style=document.createElement('style');style.id='libraryActionsStyle';style.textContent='.library-result-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:0 20px 16px}.library-result-actions button,.library-result-actions a{border:1px solid #d8e1cc;background:#f4f8ed;color:#698552;border-radius:7px;padding:10px 12px;font:11px "Microsoft YaHei",sans-serif;text-decoration:none;cursor:pointer}.library-result-actions button:disabled{opacity:.4;cursor:default}.library-result-actions>span{flex-basis:100%;font:10px/1.8 "Microsoft YaHei",sans-serif;color:#98a58b}.library-result-actions[data-library-actions-host]{padding:0;flex-basis:100%}.library-result-actions a{background:white}';document.head.append(style);}
async function blobFor(output){if(output.blob instanceof Blob)return output.blob;const element=output.canvas;if(!element?.toBlob)throw Error('请先完成当前图片处理');let blob=await new Promise((resolve,reject)=>element.toBlob(value=>value?resolve(value):reject(Error('无法导出当前图片')),'image/png'));if(output.print?.dpi){const {pngWithDpi}=await import('./pattern-designer-core.js');blob=new Blob([pngWithDpi(await blob.arrayBuffer(),output.print.dpi)],{type:'image/png'});}return blob;}
function refresh(){scheduled=false;if(!document.getElementById('toolPanels'))return;addStyle();for(const panel of document.querySelectorAll('.tt-panel[data-tool]')){const id=panel.dataset.tool;let host=panel.querySelector('[data-library-actions-host]');if(!host){host=document.createElement('div');host.dataset.libraryActionsHost='';panel.querySelector('.tt-actions')?.after(host);}if(!host)continue;if(!host.dataset.libraryMounted){host.dataset.libraryMounted='true';host.classList.add('library-result-actions');for(const [label,side]of [['保存到图库',''],['用作 A 面','A'],['用作 B 面','B']]){const button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.librarySide=side;button.onclick=async()=>{const output=registryOutput(id);if(!output||host.dataset.busy==='true')return;host.dataset.busy='true';host.querySelectorAll('button').forEach(control=>control.disabled=true);const note=host.querySelector('span');note.textContent='正在准备原尺寸图片…';try{const asset=await saveAssetDialog({...output,blob:await blobFor(output),source:output.source||'家纺工具箱 · '+id});if(asset){note.textContent='已保存到图库；可在工作台继续使用。';if(side)location.assign(applyURL(asset.id,side));}else note.textContent='已取消保存，当前结果保留。';}catch(error){note.textContent=error.message;}finally{delete host.dataset.busy;queue();}};host.append(button);}const link=document.createElement('a');link.href=libraryURL();link.textContent='打开图库 ↗';const note=document.createElement('span');note.textContent='保存与带入仅传递当前图片，不调用 AI。';host.append(link,note);}const disabled=!registryOutput(id)||host.dataset.busy==='true';for(const button of host.querySelectorAll('button'))if(button.disabled!==disabled)button.disabled=disabled;}}
function queue(){if(scheduled)return;scheduled=true;requestAnimationFrame(refresh);}
document.addEventListener('zhijing-tool-outputchange',queue);window.addEventListener('zhijing-tool-outputchange',queue);document.addEventListener('zhijing-tool-readychange',queue);new MutationObserver(queue).observe(document.getElementById('toolPanels')||document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','hidden']});queue();
